/// <summary>
/// Data contract class as a response for service <c>METSalesOrderCancelService</c>
/// </summary>
[DataContractAttribute]
class METBaseResponseContract
{
    String10            result; //string for enum METProcessingStatus
    Description255      message;

}

Method.Source:
/// <summary>
/// Method returns true if sales order is cancelled/else false
/// </summary>
/// <param name = "_result">a boolean value indicating the sales cancellation result</param>
/// <returns>returns true if sales order is cancelled/else false</returns>
[DataMemberAttribute('Result')]
public String10 parmResult(String10 _result = result)
{
    result = _result;
    return result;
}

/// <summary>
/// This method returns the message corresponding to the sales order cancellation
/// </summary>
/// <param name = "_message">a string value specifying the sales cancellation result</param>
/// <returns>returns the message corresponding to the sales order cancellation</returns>
[DataMemberAttribute('Message')]
public Description255 parmMessage(Description255 _message = message)
{
    message = _message;
    return message;
}
